SELECT COUNT(*) AS totalCount, IFNULL(SUM(CASE WHEN status = '1' THEN 1 ELSE 0 END), 0) AS successCount, IFNULL(SUM(amount), 0) AS totalAmount, IFNULL(SUM(CASE WHEN status = '1' THEN amount ELSE 0 END), 0) AS successAmount FROM recharge_records WHERE is_delete = 0
AND recharge_time >= #{dateFrom}
AND recharge_time <= #{dateTo}
